        // 纯黑空页面，与覆盖层背景一致，无视觉闪烁
        let body = br#"<!DOCTYPE html><html><body style="background:#000;margin:0"></body></html>"#;
        return http::Response::builder()
            .status(200)
            .header("Content-Type", "text/html")
            .body(Cow::from(body.to_vec()))
            .unwrap();
    }

    // ── 虚拟 engine-sdk.js（兼容游戏显式 <script src="../../engine-sdk.js"> 加载） ──
    if path_clean == "engine-sdk.js" {
        return http::Response::builder()
            .status(200)
            .header("Content-Type", "application/javascript")
            .header("Access-Control-Allow-Origin", "*")
            .body(Cow::from(GAME_ENGINE_SDK_JS.as_bytes().to_vec()))
            .unwrap();
    }

    let logical_path = LogicalPath::new(&path_clean);

    tracing::debug!(uri = %uri, path = %logical_path, "ring-asset request");

    #[expect(
        clippy::expect_used,
        reason = "uninitialised RM is an engine invariant violation"
    )]
    let rm = RESOURCE_MANAGER
        .get()
        .expect("invariant: ResourceManager not yet initialized when ring-asset request arrived");

    let mime = guess_mime(&path_clean);

    match rm.read_bytes(&logical_path) {
        Ok(bytes) => {
            // games/*/**.html: 自动注入 engine JS SDK（postMessage 桥接）
            let body = if path_clean.starts_with("games/") && mime == "text/html" {
                let html = String::from_utf8_lossy(&bytes);
                let injected = inject_engine_sdk(&html);
                Cow::from(injected.into_bytes())
            } else {
                Cow::from(bytes)
            };
            http::Response::builder()
                .status(200)
                .header("Content-Type", mime)
                .header("Access-Control-Allow-Origin", "*")
                .body(body)
                .unwrap()
        }
        Err(e) => {
            tracing::warn!(path = %logical_path, error = %e, "ring-asset 404");
            http::Response::builder()
                .status(404)
                .header("Content-Type", "text/plain")
                .body(Cow::from(format!("Not Found: {logical_path}").into_bytes()))
                .unwrap()
        }
    }
}

#[expect(
    clippy::string_slice,
    reason = "slicing ASCII hex pairs at verified byte boundaries"
)]

