pub struct ShakeAnimation {
    pub amplitude_x: f32,
    pub amplitude_y: f32,
    pub duration: f32,
    pub elapsed: f32,
}

/// Host 侧 Signal 等待的具体种类。
///
/// 与 `vn_runtime::command::SIGNAL_*` 常量一一对应，
/// 编译期保证穷举，消除字符串拼写错误风险。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SignalKind {
    SceneTransition,
    TitleCard,
    SceneEffect,
    Cutscene,
}

/// Host 侧的等待状态
#[derive(Debug, Clone, PartialEq, Serialize)]
pub enum WaitingFor {
    Nothing,
    Click,
