use dioxus::prelude::*;
use vn_runtime::command::TextMode;

use crate::{
    render_state::{HostScreen, PlaybackMode, RenderState},
    screen_defs::ActionDef,
    state::AppState,
};

/// 底部快捷菜单（数据驱动，从 screens.json `quick_menu.buttons` 渲染）
///
/// 位于对话框内部底边居中。仅在 `InGame` + ADV 模式且 UI 可见时显示。
#[component]
pub fn QuickMenu(render_state: Signal<RenderState>) -> Element {
    let app_state = use_context::<AppState>();
    let rs = render_state.read();

    // 仅在 InGame + ADV 模式 + ui_visible 时显示（NVL 模式无 quick menu）
    if rs.host_screen != HostScreen::InGame || rs.text_mode == TextMode::NVL || !rs.ui_visible {
        return rsx! {};
    }

    let is_skip = rs.playback_mode == PlaybackMode::Skip;
    let is_auto = rs.playback_mode == PlaybackMode::Auto;

    // 从 screen_defs 获取按钮列表
    let buttons = {
        let Ok(inner) = app_state.inner.lock() else {
            return rsx! {};
        };
        let Some(svc) = inner.services.as_ref() else {
            return rsx! {};
        };
        svc.screen_defs.quick_menu.buttons.clone()
    };

    rsx! {
        div { class: "vn-quick-menu",
            for btn in &buttons {
                {
                    let label = btn.label.clone();
                    let action = btn.action.clone();
                    let is_active = matches!(
                        (&action, is_skip, is_auto),
                        (ActionDef::ToggleSkip, true, _) | (ActionDef::ToggleAuto, _, true)
                    );
                    let class_name = if is_active {
                        "vn-quick-menu__btn vn-quick-menu__btn--active"
                    } else {
                        "vn-quick-menu__btn"
                    };
                    let app = app_state.clone();

                    rsx! {
                        button {
                            key: "{label}",
                            class: "{class_name}",
                            onclick: move |evt: Event<MouseData>| {
                                evt.stop_propagation();
                                if let Ok(mut inner) = app.inner.lock() {
                                    inner.execute_action(&action);
                                }
                            },
                            "{label}"
                        }
                    }
                }
            }
        }
    }
}

use dioxus::prelude::*;

use crate::{screen_defs::ActionDef, state::AppState};

/// 待确认操作
#[derive(Debug, Clone)]
pub(crate) struct PendingConfirm {
    /// 弹窗消息
    pub message: String,
    /// 用户确认后执行的动作
    pub on_confirm: ActionDef,
}

/// 模态确认弹窗组件
///
/// 全屏遮罩 + 居中面板 + 消息 + 确定/取消按钮。
/// 通过 `use_context::<Signal<Option<PendingConfirm>>>()` 控制显隐。
#[component]
pub fn ConfirmDialog() -> Element {
    let mut pending = use_context::<Signal<Option<PendingConfirm>>>();
    let app_state = use_context::<AppState>();

    let confirm = pending.read();
    let Some(ref data) = *confirm else {
        return rsx! {};
    };

    let message = data.message.clone();
    let action = data.on_confirm.clone();

    rsx! {
        div {
            class: "confirm-overlay",
            // 点击遮罩 = 取消
            onclick: move |_| {
                pending.set(None);
            },

            div {
                class: "confirm-panel",
                // 阻止面板内点击冒泡到遮罩
                onclick: move |evt: Event<MouseData>| {
                    evt.stop_propagation();
                },

                // 消息文字
                div { class: "confirm-panel__message", "{message}" }

                // 按钮区
                div { class: "confirm-panel__buttons",
                    button {
                        class: "confirm-panel__btn",
                        onclick: {
                            let app = app_state;
                            move |_| {
                                pending.set(None);
                                if matches!(action, ActionDef::Exit) {
                                    dioxus::desktop::window().close();
                                } else if let Ok(mut inner) = app.inner.lock() {
                                    inner.execute_action(&action);
                                }
                            }
                        },
                        "确定"
                    }
                    button {
                        class: "confirm-panel__btn",
                        onclick: move |_| {
                            pending.set(None);
                        },
                        "取消"
                    }
                }
            }
        }
    }
}

