pub struct UserSettings {
    pub bgm_volume: f32,
    pub sfx_volume: f32,
    pub text_speed: f32,
    pub auto_delay: f32,
    pub fullscreen: bool,
    #[serde(default)]
    pub muted: bool,
}

impl Default for UserSettings {
    fn default() -> Self {
        Self {
            bgm_volume: 80.0,
            sfx_volume: 100.0,
            text_speed: 40.0,
            auto_delay: 2.0,
            fullscreen: false,
            muted: false,
        }
