    let screen_defs = ScreenDefinitions::load(&rm)?;

    inner.persistent_store = PersistentStore::load(&saves_dir);
    inner.services = Some(Services {
        audio: am,
        resources: rm,
        saves: sm,
        config: cfg,
        manifest: mf,
        layout,
        screen_defs,
    });
    info!("子系统初始化完成");
    Ok(())
}

