let cli = Cli::parse();
let sh = Shell::new()?;

match cli.command {
    XtaskCommand::CheckAll => {
        let fmt_check = std::process::Command::new("cargo")
            .args(["fmt", "--all", "--", "--check"])
            .status()
            .context("cargo fmt --check failed to start")?;
        if !fmt_check.success() {
            eprintln!("\nfmt 检查发现差异，正在 apply...");
            run("cargo fmt --all", &sh, "cargo", &["fmt", "--all"])?;
        }

        run(
            "cargo clippy --workspace --fix --allow-dirty",
            &sh,
            "cargo",
            &["clippy", "--workspace", "--fix", "--allow-dirty"],
        )?;

        run(
            "cargo test --workspace --quiet",
            &sh,
            "cargo",
            &["test", "--workspace", "--quiet"],
        )?;

        if !fmt_check.success() {
            anyhow::bail!("fmt check failed");
